// rouletteApi.js
// 이 프로젝트는 클라이언트 전용 룰렛 모드로 변경되었습니다.
// 더 이상 서버 호출을 사용하지 않으므로 이 파일은 비활성화되어 있습니다.
// (파일을 완전히 삭제하려면 수동으로 제거하세요.)

export const getRouletteRewards = async () => {
  throw new Error('rouletteApi is deprecated in client-only mode. Use local rewards in pages/components instead.');
};

export const spinRoulette = async () => {
  throw new Error('rouletteApi is deprecated in client-only mode. Use local spin logic in pages/components instead.');
};
